SELECT cm.id, cm.article_id, cm.parent_id, cm.user_id, cm.nickname, cm.email, cm.content, cm.status, cm.create_time, a.title AS articleTitle FROM t_comment cm JOIN t_article a ON a.id = cm.article_id
AND cm.status = #{status}
AND cm.article_id = #{articleId}
AND (cm.content LIKE CONCAT('%', #{keyword}, '%') OR cm.nickname LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY cm.create_time DESC, cm.id DESC

SELECT id, article_id, parent_id, user_id, nickname, email, content, status, create_time
FROM t_comment WHERE parent_id = #{parentId}
ORDER BY create_time ASC, id ASC
